import React, { useState } from "react";
import { useNavigate } from "react-router-dom";
import "./LoginPage.css";

function LoginPage() {
  const [email, setEmail] = useState("arnav123@university.edu"); // demo prefill
  const [password, setPassword] = useState("");
  const navigate = useNavigate();

  const handleLogin = (e) => {
    e.preventDefault();
    // TODO: connect to backend auth
    navigate("/dashboard");
  };

  return (
    <div className="login-container">
      <header className="login-header">
        <img src="/nityo-logo.png" alt="Nityo Logo" className="login-logo" />
        <h2 className="app-title">Nityo</h2>
        <p className="tagline">The Rhythm of Done. Discipline in Motion.</p>
      </header>

      <div className="login-card">
        <form onSubmit={handleLogin}>
          <input
            type="email"
            placeholder="Enter your email"
            value={email}
            onChange={(e) => setEmail(e.target.value)}
            required
          />
          <input
            type="password"
            placeholder="Enter your password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            required
          />
          <button type="submit">Login</button>
        </form>
        <p>
          Don’t have an account?{" "}
          <span className="link" onClick={() => navigate("/register")}>
            Register here
          </span>
        </p>
      </div>
    </div>
  );
}

export default LoginPage;
